ALTER TABLE public.monthly_post_usage ADD COLUMN IF NOT EXISTS module_scope text NOT NULL DEFAULT 'vehicle';
UPDATE public.monthly_post_usage u SET module_scope='work' WHERE EXISTS(SELECT 1 FROM public.posts p WHERE p.id=u.post_id AND p.module='job') OR EXISTS(SELECT 1 FROM public.free_work_entries e WHERE e.id=u.post_id);
CREATE OR REPLACE FUNCTION public.subscription_posts_used(_user uuid,_start timestamptz) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM (SELECT post_id FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=_start AND module_scope='vehicle' UNION SELECT id FROM public.posts WHERE user_id=_user AND module='vehicle' AND created_at>=_start) recorded $$;
DO $$ DECLARE def text; r record; BEGIN SELECT pg_get_functiondef('public.consume_post_slot(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user) ON CONFLICT DO NOTHING; RETURN;','INSERT INTO public.monthly_post_usage(post_id,user_id,module_scope) VALUES(_id,_user,CASE WHEN public.has_role(_user,''admin'') AND NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_id AND module=''job'') AND NOT EXISTS(SELECT 1 FROM public.free_work_entries WHERE id=_id) THEN ''vehicle'' ELSE ''work'' END) ON CONFLICT DO NOTHING; RETURN;'); EXECUTE def;
FOR r IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('open_vehicle_chat','open_vehicle_demand_chat','ring_vehicle_demand','ring_vehicle_board') LOOP def:=pg_get_functiondef(r.oid); def:=replace(def,'public.has_paid_bell(caller)','public.vehicle_contact_access(caller)'); EXECUTE def; END LOOP;
SELECT pg_get_functiondef('public.can_call_member(uuid)'::regprocedure) INTO def; def:=replace(def,'AND public.has_paid_bell(auth.uid()) AND public.has_paid_bell(_other)','AND (public.has_role(auth.uid(),''admin'') OR public.has_role(_other,''admin'') OR (public.has_paid_bell(auth.uid()) AND public.has_paid_bell(_other)))'); EXECUTE def; END $$;
ALTER POLICY paid_demand_read ON public.vehicle_bell_demands TO authenticated USING(public.vehicle_contact_access(auth.uid()) AND public.account_allowed(user_id));